app.post('/form', async c => {
  const body = await c.req.parseBody();
  return c.json({
    name: typeof body.name === 'string' ? body.name : ''
  });
});

import { validator } from 'hono/validator';
app.post('/users', validator('json', (value, c) => {
  if (!value || typeof value.name !== 'string')
    return c.json({ error: 'invalid name' }, 400);
  return { name: value.name };
}), c => c.json(c.req.valid('json'), 201));

import { z } from 'zod';
import { zValidator } from '@hono/zod-validator';
app.post(
  '/users',
  zValidator('json', z.object({ name: z.string().min(1) })),
  c => c.json(c.req.valid('json'), 201)
);

app.use('*', async (c, next) => {
  console.log(c.req.method, c.req.path);
  await next();
  c.header('X-App', 'sample');
});

import { createMiddleware } from 'hono/factory';
const log = createMiddleware(async (c, next) => {
  console.log(c.req.path);
  await next();
});
app.use('*', log);

type Env = {
  Variables: {
    requestId: string
  }
};
const traced = new Hono<Env>();
traced.use('*', async (c, next) => {
  c.set('requestId', crypto.randomUUID());
  await next()
});
traced.get('/', c => c.json({ id: c.get('requestId') }));

type Env = {
  Bindings: {
    APP_NAME: string
  }
};
const worker = new Hono<Env>();
worker.get('/', c => c.text(c.env.APP_NAME));

import { HTTPException } from 'hono/http-exception';
app.get('/private', () => {
  throw new HTTPException(401, { message: 'Unauthorized' })
});

app.onError((err, c) => {
  if (err instanceof HTTPException)
    return err.getResponse();
  console.error(err);
  return c.json({ error: 'internal error' }, 500);
});

import { getCookie, setCookie, deleteCookie } from 'hono/cookie';
app.post('/theme', c => {
  setCookie(c, 'theme', 'dark', { httpOnly: true, sameSite: 'Lax', path: '/' });
  return c.json({ ok: true })
});

const routes = app.get('/health', c => c.json({ ok: true }));
export type AppType = typeof routes;
